// Stats must use atomic operations
type Stats struct {
    Hits, Misses, LoadErrors int64
}
atomic.AddInt64(&c.stats.Hits, 1)

// Set() needs the lock!
func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.data[key] = &CacheEntry{...}
}

// cleanup() must hold lock during iteration
func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()
    for key, entry := range c.data {
        if time.Now().After(entry.ExpiresAt) {
            delete(c.data, key)
        }
    }
}

// GetMulti() needs sync.WaitGroup and mutex for results
func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            if value, err := c.Get(ctx, k); err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }
    wg.Wait()
    return results
}

